CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,subject text UNIQUE NOT NULL,display_name text NOT NULL,platform_admin boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS teams(id text PRIMARY KEY,organization_id text REFERENCES organizations(id),name text NOT NULL,age_division text NOT NULL CHECK(age_division IN ('M11','M13','M15','M18')),season_id text NOT NULL,plan_code text NOT NULL DEFAULT 'FREE' CHECK(plan_code IN ('FREE','TEAM_PRO')),subscription_status text NOT NULL DEFAULT 'FREE',effective_from timestamptz,effective_to timestamptz,billing_provider_ref text);
CREATE TABLE IF NOT EXISTS memberships(team_id text REFERENCES teams(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('TEAM_ADMIN','COACH','PLAYER')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS projects(id text PRIMARY KEY,team_id text NOT NULL REFERENCES teams(id),name text NOT NULL,scope text NOT NULL CHECK(scope IN ('breakout','forecheck')),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED')),revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,team_id));
CREATE TABLE IF NOT EXISTS resources(id text PRIMARY KEY,team_id text NOT NULL,project_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('system','scenario','sequence','lesson')),name text NOT NULL,payload jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,team_id) REFERENCES projects(id,team_id),UNIQUE(id,team_id));
CREATE TABLE IF NOT EXISTS resource_versions(id text PRIMARY KEY,team_id text NOT NULL,resource_id text NOT NULL,version integer NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,checksum text NOT NULL,blob_key text,published_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(resource_id,team_id) REFERENCES resources(id,team_id),UNIQUE(resource_id,version),UNIQUE(id,team_id));
CREATE TABLE IF NOT EXISTS catalog(id text PRIMARY KEY,name text NOT NULL,category text NOT NULL,template text NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,checksum text NOT NULL,created_by text NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assignments(id text PRIMARY KEY,team_id text NOT NULL REFERENCES teams(id),lesson_version_id text,catalog_id text REFERENCES catalog(id),target_user_id text,assigned_by text NOT NULL REFERENCES users(id),due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(lesson_version_id,team_id) REFERENCES resource_versions(id,team_id),FOREIGN KEY(team_id,target_user_id) REFERENCES memberships(team_id,user_id),CHECK((lesson_version_id IS NULL)<>(catalog_id IS NULL)),UNIQUE(id,team_id));
CREATE TABLE IF NOT EXISTS progress(assignment_id text NOT NULL REFERENCES assignments(id),user_id text NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN ('NOT_STARTED','IN_PROGRESS','COMPLETED')),watched_ticks integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(assignment_id,user_id));
CREATE TABLE IF NOT EXISTS invitations(id text PRIMARY KEY,team_id text NOT NULL REFERENCES teams(id),token_hash text UNIQUE NOT NULL,role text NOT NULL CHECK(role IN ('TEAM_ADMIN','COACH','PLAYER')),expires_at timestamptz NOT NULL,used_at timestamptz,revoked_at timestamptz,created_by text NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),csrf_token text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oidc_states(state_hash text PRIMARY KEY,verifier text NOT NULL,nonce text NOT NULL,redirect_uri text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(actor_id text NOT NULL REFERENCES users(id),operation text NOT NULL,key text NOT NULL,body_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,operation,key));
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,actor_id text NOT NULL REFERENCES users(id),team_id text REFERENCES teams(id),action text NOT NULL,target_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS resources_team_project ON resources(team_id,project_id);
CREATE INDEX IF NOT EXISTS versions_team ON resource_versions(team_id,resource_id);
CREATE INDEX IF NOT EXISTS memberships_user ON memberships(user_id,active);
CREATE INDEX IF NOT EXISTS projects_team_status ON projects(team_id,status);
CREATE INDEX IF NOT EXISTS assignments_team_user ON assignments(team_id,target_user_id);
CREATE INDEX IF NOT EXISTS audit_team_time ON audit_events(team_id,created_at);
CREATE OR REPLACE FUNCTION reject_immutable_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_PUBLISHED_VERSION'; END; $$;
DROP TRIGGER IF EXISTS immutable_versions ON resource_versions;
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON resource_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_version();
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;

ALTER TABLE catalog ADD COLUMN IF NOT EXISTS series_id text;
CREATE UNIQUE INDEX IF NOT EXISTS catalog_series_version ON catalog((COALESCE(series_id,id)),version);
DROP TRIGGER IF EXISTS immutable_catalog ON catalog;
CREATE TRIGGER immutable_catalog BEFORE UPDATE OR DELETE ON catalog FOR EACH ROW EXECUTE FUNCTION reject_immutable_version();
